function exportableState() { return { schemaVersion: 8, projects: state.projects, transactions: state.transactions, budgets: state.budgets, recurring: state.recurring, estimates: state.estimates, employees: state.employees, timeEntries: state.timeEntries, events: state.events, settings: state.settings }; }
