function renderCalendar() { setText("calendar-title", monthName(calendarMonth)); const grid = $("calendar-grid"); grid.replaceChildren(); const offset = firstDayOffset(calendarMonth); for (let i = 0; i < offset; i++) { const cell = document.createElement("div"); cell.className = "calendar-cell outside"; grid.append(cell); } for (let day = 1; day <= daysInMonth(calendarMonth); day++) { const date = `${calendarMonth}-${String(day).padStart(2,"0")}`; const rows = projectRows(state.transactions).filter((row) => row.date === date); const incomes = sum(rows.filter((r) => r.type === "income" && !isPlanned(r)), (r) => r.amount); const expenses = sum(rows.filter((r) => r.type === "expense" && !isPlanned(r)), (r) => r.amount); const planned = sum(rows.filter(isPlanned), (r) => r.amount); const cell = document.createElement("button"); cell.type = "button"; cell.className = `calendar-cell${date === todayISO() ? " today" : ""}`; cell.innerHTML = `<span class="calendar-date">${day}</span><span class="calendar-values">${incomes ? `<span class="income">+${compactMoney(incomes)}</span>` : ""}${expenses ? `<span class="expense">−${compactMoney(expenses)}</span>` : ""}${planned ? `<span class="planned">· ${compactMoney(planned)}</span>` : ""}</span>`; cell.addEventListener("click", () => openDay(date)); grid.append(cell); } }

function calendarItemsForDate(date) { const items = []; for (const row of projectRows(state.transactions).filter((item) => item.date === date && !String(item.id).startsWith("estimate-payment:"))) items.push({ source: "transaction", kind: row.type === "income" ? "income" : isPlanned(row) ? "planned" : "expense", title: `${row.description || categoryLabel(row.category)} · ${money(row.amount)}`, row }); for (const event of projectRows(state.events || []).filter((item) => item.date === date)) items.push({ source: "event", kind: "event", title: `${event.time ? `${event.time} · ` : ""}${event.title}`, event }); for (const project of projectRows(state.projects).filter((item) => item.id !== "general")) { if (project.startDate === date) items.push({ source: "project", kind: "project", title: `${t("projectStart")} · ${project.name}`, project }); if (project.endDate === date) items.push({ source: "project", kind: "project", title: `${t("projectEnd")} · ${project.name}`, project }); } for (const estimate of projectRows(state.estimates).filter((item) => item.eventDate === date)) items.push({ source: "estimate", kind: "estimate", title: `${t("estimateTitle")} · ${estimate.title}`, estimate }); for (const estimate of projectRows(state.estimates)) for (const stage of estimate.paymentSchedule || []) { const stageDate = stage.status === "paid" ? stage.paidDate : stage.dueDate; if (stageDate === date) items.push({ source: "payment", kind: stage.status === "paid" ? "income" : "planned", title: `${t("paymentStage")} · ${stage.label} · ${money(stage.amount)}`, estimate, stage }); } for (const entry of projectRows(state.timeEntries || []).filter((item) => item.date === date)) items.push({ source: "hours", kind: "hours", title: `${entry.hours.toFixed(1)} h · ${projectLabel(entry.projectId)}`, entry }); return items; }
function renderCalendarV16() { setText("calendar-title", monthName(calendarMonth)); const grid = $("calendar-grid"); grid.replaceChildren(); const offset = firstDayOffset(calendarMonth); for (let i = 0; i < offset; i++) { const cell = document.createElement("div"); cell.className = "calendar-cell outside"; grid.append(cell); } for (let day = 1; day <= daysInMonth(calendarMonth); day += 1) { const date = `${calendarMonth}-${String(day).padStart(2, "0")}`; const items = calendarItemsForDate(date); const cell = document.createElement("button"); cell.type = "button"; cell.className = `calendar-cell${date === todayISO() ? " today" : ""}`; const visible = items.slice(0, 4).map((item) => `<span class="calendar-item ${escapeHTML(item.kind)}">${escapeHTML(item.title)}</span>`).join(""); const extra = items.length > 4 ? `<span class="calendar-more">+${items.length - 4} ${escapeHTML(t("moreItems"))}</span>` : ""; cell.innerHTML = `<span class="calendar-date">${day}</span><span class="calendar-values">${visible || `<span class="calendar-empty-dot">${escapeHTML(t("noCalendarItems"))}</span>`}${extra}</span>`; cell.addEventListener("click", () => openDay(date)); grid.append(cell); } }
renderCalendar = renderCalendarV16;

function renderBudgets() { setText("budget-month-label", monthName(budgetMonth)); renderBudgetMethod(); const list = $("budget-list"); list.replaceChildren(); const budgets = projectRows(state.budgets).filter((row) => budgetAllowance(row, budgetMonth) > 0).sort((a,b) => categoryLabel(a.category).localeCompare(categoryLabel(b.category), locale())); $("budget-empty").hidden = budgets.length > 0; for (const budget of budgets) { const allowance = budgetAllowance(budget, budgetMonth); const spent = projectRows(state.transactions).filter((row) => row.date.startsWith(budgetMonth) && row.category === budget.category && row.projectId === budget.projectId && row.type === "expense" && !isPlanned(row)).reduce((total, row) => total + row.amount, 0); const percent = allowance ? spent / allowance * 100 : 0; const projectNote = activeProjectId() === "all" ? `<small class="frequency-badge">${escapeHTML(projectLabel(budget.projectId))}</small>` : ""; const card = document.createElement("article"); card.className = "budget-card"; card.innerHTML = `<header><div><h3>${escapeHTML(categoryLabel(budget.category))}</h3><small class="frequency-badge">${escapeHTML(frequencyLabel(budget.frequency))}</small>${projectNote}</div><button class="edit-link" type="button">${t("edit")}</button></header><div class="budget-values"><strong>${money(spent)}</strong><span>${language() === "en" ? "of" : "sur"} ${money(allowance)}</span></div><div class="progress-track"><i class="${percent > 100 ? "over" : ""}" style="width:${Math.min(100, percent)}%"></i></div><footer><span>${Math.round(percent)} % ${t("used")}</span><span>${t("remaining")} ${money(Math.max(0, allowance - spent))}</span></footer>`; q(".edit-link", card).addEventListener("click", () => openBudget(budget.id)); list.append(card); } }

function renderBudgetMethod() { const rows = rowsInMonth(budgetMonth); const income = sum(rows.filter((row) => row.type === "income"), (row) => row.amount); const allocated = sum(projectRows(state.budgets), (budget) => budgetAllowance(budget, budgetMonth)); const remaining = roundMoney(income - allocated); setText("method-income", money(income)); setText("method-allocated", money(allocated)); setText("method-unassigned", money(remaining)); }

