function estimateReconciliation(estimate) { const itemIds = new Set((estimate.items || []).map((item) => item.id)); const expenses = state.transactions.filter((row) => row.projectId === estimate.projectId && row.type === "expense" && !isPlanned(row)); const linkedExpenses = expenses.filter((row) => row.estimateId === estimate.id && itemIds.has(row.estimateItemId)); const labor = state.timeEntries.filter((row) => row.projectId === estimate.projectId && row.estimateId === estimate.id && itemIds.has(row.estimateItemId)); const actual = sum(linkedExpenses, (row) => row.netAmount ?? row.amount) + sum(labor, (row) => row.hours * (row.costRate || 0)); const unforeseen = sum(expenses.filter((row) => row.estimateId !== estimate.id || !itemIds.has(row.estimateItemId)), (row) => row.netAmount ?? row.amount); const laborHours = sum(labor, (row) => row.hours); return { actual: roundMoney(actual), variance: roundMoney(estimate.subtotal - actual), unforeseen: roundMoney(unforeseen), laborHours }; }
