async function submitTemplate(event) { event.preventDefault(); const name = $("template-name").value.trim(); if (!name) { $("template-error").textContent = t("templateName"); return; } const old = templateList().find((template) => template.id === editingTemplateId); const template = { id: editingTemplateId || `template-${uid()}`, name, builtin: old?.builtin === true, layout: $("template-layout").value, primary: $("template-primary").value, accent: $("template-accent").value, showLogo: $("template-show-logo").checked, showPaymentSchedule: $("template-show-payments").checked, footer: $("template-footer").value.trim() }; const templates = editingTemplateId ? templateList().map((item) => item.id === editingTemplateId ? template : item) : [...templateList(), template]; $("template-dialog").close(); await commit({ ...state, settings: { ...state.settings, branding: { ...state.settings.branding, templates } } }, t("templateSaved")); }
