async function readLogoDataUrl(file) { if (!file || !file.type.startsWith("image/")) throw Error(); if (file.size > 4_000_000) throw Error(); return new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => { const image = new Image(); image.onload = () => { const max = 900; const scale = Math.min(1, max / Math.max(image.width, image.height)); const canvas = document.createElement("canvas"); canvas.width = Math.max(1, Math.round(image.width * scale)); canvas.height = Math.max(1, Math.round(image.height * scale)); canvas.getContext("2d").drawImage(image, 0, 0, canvas.width, canvas.height); resolve(canvas.toDataURL("image/png")); }; image.onerror = reject; image.src = reader.result; }; reader.onerror = reject; reader.readAsDataURL(file); }); }
async function handleLogoChange(event) { try { brandingLogoDraft = await readLogoDataUrl(event.target.files?.[0]); renderBrandingSettings(); } catch { showToast(language() === "en" ? "Choose a valid image under 4 MB." : "Choisis une image valide de moins de 4 Mo."); event.target.value = ""; } }
