function renderCategoryManager() { const container = $("category-list"); if (!container) return; container.replaceChildren(); for (const type of ["income", "expense"]) { const group = document.createElement("section"); group.className = "category-group"; const heading = document.createElement("h4"); heading.textContent = type === "income" ? t("incomeCategory") : t("expenseCategory"); group.append(heading); const list = document.createElement("div"); list.className = "category-chips"; const categories = categoryList(type); for (const category of categories) { const chip = document.createElement("span"); chip.className = "category-chip"; chip.innerHTML = `<span>${escapeHTML(categoryLabel(category))}</span>`; const remove = document.createElement("button"); remove.type = "button"; remove.className = "category-remove"; remove.textContent = "×"; remove.title = t("deleteCategory"); remove.setAttribute("aria-label", `${t("deleteCategory")} ${categoryLabel(category)}`); remove.onclick = () => deleteCategory(type, category); chip.append(remove); list.append(chip); } if (!categories.length) { const empty = document.createElement("span"); empty.className = "category-empty-note"; empty.textContent = t("noCategories"); list.append(empty); } group.append(list); container.append(group); } }
