function paymentScheduleDraft(total) { return qa(".estimate-payment-row", $("estimate-payments")).map((row, index) => { const percentage = Number(q(".payment-stage-percentage", row).value) || 0; const status = q(".payment-stage-status", row).value; const paidDate = status === "paid" ? (q(".payment-stage-paid-date", row).value || todayISO()) : ""; return { id: row.dataset.paymentId || uid(), label: q(".payment-stage-label", row).value.trim() || `${t("paymentStage")} ${index + 1}`, percentage, amount: roundMoney(total * percentage / 100), dueDate: q(".payment-stage-due", row).value, status, paidDate }; }).filter((stage) => stage.percentage > 0); }
function refreshPaymentTotals() { const total = Number($("estimate-total")?.dataset.value || 0); const percentage = qa(".estimate-payment-row", $("estimate-payments")).reduce((sumValue, row) => sumValue + (Number(q(".payment-stage-percentage", row).value) || 0), 0); qa(".estimate-payment-row", $("estimate-payments")).forEach((row) => { const stagePercentage = Number(q(".payment-stage-percentage", row).value) || 0; q(".payment-stage-amount", row).textContent = money(total * stagePercentage / 100); }); const totalElement = $("estimate-payment-total"); if (totalElement) { totalElement.textContent = `${t("paymentScheduleTotal")} : ${percentage.toFixed(2)} %`; totalElement.classList.toggle("warning", percentage > 0 && Math.abs(percentage - 100) > 0.01); } }
function refreshEstimateTotals() { if (!$("estimate-items")) return; const items = estimateDraftItems(); qa(".estimate-item-row", $("estimate-items")).forEach((row) => { const quantity = Number(q(".estimate-item-quantity", row).value) || 0; const unitPrice = roundMoney(q(".estimate-item-price", row).value); const total = roundMoney(quantity * unitPrice); const totalElement = q(".estimate-item-total", row); if (totalElement) totalElement.textContent = money(total); }); const subtotal = sum(items, (item) => item.total); const taxCode = validTaxCode($("estimate-tax-code")?.value); const breakdown = taxBreakdown(subtotal, taxCode, state.settings.taxRates, false); const total = roundMoney(subtotal + breakdown.taxAmount); setText("estimate-subtotal", money(subtotal)); setText("estimate-tax", money(breakdown.taxAmount)); setText("estimate-total", money(total)); if ($("estimate-total")) $("estimate-total").dataset.value = String(total); refreshPaymentTotals(); }
function openEstimate(id = null) { editingEstimateId = id; const row = state.estimates.find((estimate) => estimate.id === id); ensureEstimateTemplateControl(); $("estimate-form").reset(); $("estimate-dialog-title").textContent = row ? t("editEstimate") : t("addEstimate"); populateProjectSelect("estimate-project", row?.projectId || (activeProjectId() === "all" ? "general" : activeProjectId())); $("estimate-number").value = row?.number || `S-${String(state.estimates.length + 1).padStart(4, "0")}`; $("estimate-client").value = row?.client || activeProject()?.client || ""; $("estimate-title").value = row?.title || ""; renderTemplateOptions(row?.templateId || state.settings.branding.defaultTemplateId); $("estimate-status").value = row?.status || "draft"; $("estimate-date").value = row?.issueDate || todayISO(); $("estimate-date").readOnly = true; $("estimate-valid-until").value = row?.eventDate || row?.validUntil || ""; $("estimate-tax-code").value = row?.taxCode || (row ? "none" : "gst_qst"); $("estimate-payment-terms").value = row?.paymentTerms || ""; $("estimate-notes").value = row?.notes || ""; $("estimate-error").textContent = ""; $("estimate-delete").hidden = !row; $("estimate-export").hidden = !row; $("estimate-items").replaceChildren(); (row?.items?.length ? row.items : [{}]).forEach((item) => addEstimateItemRow(item)); $("estimate-payments").replaceChildren(); (row?.paymentSchedule || []).forEach((stage) => addPaymentStageRow(stage)); $("estimate-payments-empty").hidden = Boolean(row?.paymentSchedule?.length); refreshEstimateTotals(); $("estimate-dialog").showModal(); }
async function submitEstimate(event) { event.preventDefault(); const items = estimateDraftItems(); if (!$("estimate-title").value.trim() || !items.length) { $("estimate-error").textContent = t("estimateItems"); return; } const subtotal = sum(items, (item) => item.total); const taxCode = validTaxCode($("estimate-tax-code").value); const breakdown = taxBreakdown(subtotal, taxCode, state.settings.taxRates, false); const taxRate = breakdown.taxRate; const tax = breakdown.taxAmount; const total = roundMoney(subtotal + tax); const old = state.estimates.find((estimate) => estimate.id === editingEstimateId); const eventDate = $("estimate-valid-until").value; const issueDate = old?.issueDate || $("estimate-date").value || todayISO(); const row = { id: editingEstimateId || uid(), projectId: $("estimate-project").value || "general", number: $("estimate-number").value.trim(), title: $("estimate-title").value.trim(), client: $("estimate-client").value.trim(), status: $("estimate-status").value, issueDate, eventDate, validUntil: eventDate, templateId: $("estimate-template").value || state.settings.branding.defaultTemplateId, notes: $("estimate-notes").value.trim(), paymentTerms: $("estimate-payment-terms").value.trim(), paymentSchedule: paymentScheduleDraft(total), items, subtotal, taxCode, taxRate, tax, gstAmount: breakdown.gstAmount, qstAmount: breakdown.qstAmount, hstAmount: breakdown.hstAmount, total, createdAt: old?.createdAt || nowISO(), updatedAt: nowISO() }; const projects = state.projects.map((project) => project.id === row.projectId && !project.primaryEstimateId ? { ...project, primaryEstimateId: row.id, updatedAt: nowISO() } : project); const estimates = editingEstimateId ? state.estimates.map((estimate) => estimate.id === editingEstimateId ? row : estimate) : [...state.estimates, row]; $("estimate-dialog").close(); await commit({ ...state, projects, estimates }, t("estimateSaved")); }
