function mergeImportedRows(existing, incoming) { const map = new Map((existing || []).map((row) => [row.id, row])); for (const row of incoming || []) { const id = row.id && !map.has(row.id) ? row.id : uid(); map.set(id, { ...row, id }); } return [...map.values()]; }
