function polishEstimateExportWindow(win, estimateId) {
  if (!win?.document) return;
  const header = win.document.querySelector(".estimate-header"); const brandColumn = header?.querySelector(".brand-column"); const logoZone = header?.querySelector(".logo-zone"); const estimateHeading = header?.querySelector(".estimate-heading"); const companyBlock = brandColumn?.querySelector(".company-block");
  if (header && brandColumn && logoZone && estimateHeading && companyBlock) {
    brandColumn.replaceChildren(estimateHeading, companyBlock); header.append(logoZone); header.style.gridTemplateColumns = "minmax(0,1fr) 240px"; header.style.gap = "48px"; header.style.alignItems = "center"; header.style.padding = "38px 0 34px"; estimateHeading.style.textAlign = "left"; estimateHeading.style.paddingTop = "0"; logoZone.style.width = "230px"; logoZone.style.height = "180px"; logoZone.style.marginLeft = "auto"; logoZone.style.marginRight = "0"; logoZone.style.marginTop = "8px"; const logo = logoZone.querySelector(".estimate-logo"); if (logo) { logo.style.maxWidth = "210px"; logo.style.maxHeight = "150px"; }
    if (win.innerWidth && win.innerWidth <= 700) { header.style.gridTemplateColumns = "1fr"; header.style.gap = "25px"; estimateHeading.style.textAlign = "left"; logoZone.style.width = "100%"; logoZone.style.height = "150px"; logoZone.style.margin = "0"; }
  }
  win.document.querySelectorAll(".estimate-number").forEach((element) => element.remove()); win.document.querySelector(".info-grid")?.remove(); win.document.querySelector(".document-footer")?.remove(); win.document.querySelector(".pdf-hint")?.remove(); const estimate = state.estimates.find((item) => item.id === estimateId); if (estimate) win.document.title = estimate.title || t("estimateTitle");
  try { win.history.replaceState({}, "", `${window.location.origin}${window.location.pathname}#estimate-${encodeURIComponent(estimateId || "document")}`); } catch { /* Certains navigateurs verrouillent l’URL d’une fenêtre d’impression. */ }
}

const exportEstimateClientV15Base = exportEstimateClient;
exportEstimateClient = function exportEstimateClientWithPolish(id = editingEstimateId) {
  const nativeOpen = window.open;
  window.open = (...args) => { const child = nativeOpen.apply(window, args); if (child?.document) { const nativeClose = child.document.close.bind(child.document); child.document.close = () => { nativeClose(); polishEstimateExportWindow(child, id); }; } return child; };
  try { return exportEstimateClientV15Base(id); } finally { window.open = nativeOpen; }
};
